import math

class PhiAccrualDetector:
    def __init__(self, threshold: float = 8.0, max_window: int = 10):
        self.threshold = threshold
        self.max_window = max_window
        self.intervals = []
        self.last_ts = None

    def heartbeat(self, timestamp: float) -> None:
        if self.last_ts is not None:
            interval = timestamp - self.last_ts
            if interval > 0:
                self.intervals.append(interval)
                if len(self.intervals) > self.max_window:
                    self.intervals.pop(0)
        self.last_ts = timestamp

    def phi(self, now: float) -> float:
        if self.last_ts is None or not self.intervals or now <= self.last_ts:
            return 0.0

        delta = now - self.last_ts
        mean = sum(self.intervals) / len(self.intervals)
        if mean <= 0:
            return 0.0

        return delta / (mean * math.log(10))

    def is_suspect(self, now: float) -> bool:
        return self.phi(now) >= self.threshold
